<?php
declare(strict_types=1);
/** USD/PKR forward contracts. All writers must hold the Accounts storage lock. */
function fwb_entity(string $e):string {if(!in_array($e,['TTI','BRM'],true))throw new DomainException('USD/PKR forward bookings are available only in Pakistan company books.');return $e;}
function fwb_today():string{return (new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi')))->format('Y-m-d');}
function fwb_date(mixed $v,bool $future=false):string {$v=(string)$v;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v||(!$future&&$v>fwb_today()))throw new DomainException('Enter a valid date, no later than today.');return $v;}
function fwb_number(mixed $v,string $name,int $precision=2,bool $zero=false):float {if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||(!$zero&&(float)$v<=0)||(float)$v>100000000000)throw new DomainException('Enter a valid '.$name.'.');$n=round((float)$v,$precision);if(!$zero&&$n<=0)throw new DomainException($name.' must be greater than zero.');return $n;}
function fwb_days(mixed $v,bool $zero):int {if(!preg_match('/^\d{1,5}$/',(string)$v)||(!$zero&&(int)$v===0)||(int)$v>36500)throw new DomainException('Enter calendar days: AB may be zero; CD must be positive.');return (int)$v;}
function fwb_text(mixed $v,int $max=180):string {$v=trim((string)$v);if(strlen($v)>$max)throw new DomainException('The contract number or note is too long.');return $v;}
function fwb_banks(string $e):array {
 fwb_entity($e);$out=[];
 foreach((array)(tt_list_masters()['banks']??[]) as $r){$v=(array)($r['values']??[]);$linked=strtoupper((string)($v[1]??''));$owner=str_contains($linked,'BUKSH')||preg_match('/(^|\W)BRM($|\W)/',$linked)?'BRM':(str_contains($linked,'TRANSTRADE INTERNATIONAL')||preg_match('/(^|\W)TTI($|\W)/',$linked)?'TTI':'');
 if($owner!==$e||strtoupper((string)($v[7]??''))!=='PKR'||!in_array($v[0]??'',['Company Account','Proprietor / Owner Account','Personal Account'],true)||strcasecmp((string)($v[13]??'Active'),'Inactive')===0)continue;
 if(trim((string)($v[8]??''))===''&&trim((string)($v[9]??''))==='')continue;$id=(string)$r['id'];if(function_exists('tt_bank_can_transact')&&!tt_bank_can_transact($id))continue;
 $out[]=['id'=>$id,'name'=>(string)($v[4]??''),'label'=>implode(' · ',array_filter([$v[4]??'',($v[8]??'')?:($v[9]??''),$v[3]??''])),'accountTitle'=>(string)($v[3]??'')];
 }return $out;
}
function fwb_bank(string $e,string $id):array {foreach(fwb_banks($e) as $b)if($b['id']===$id)return $b;throw new DomainException('Choose an active PKR bank account in this Pakistan company.');}
function fwb_usage(array $s,array $b,?string $asOf=null):array {
 $used=0;$history=[];
 foreach((array)($s['exportReceipts']??[]) as $r){if(($r['forwardBookingId']??'')!==$b['id']||($r['entity']??'')!==$b['entity']||($asOf!==null&&($r['date']??'')>$asOf))continue;$active=($r['status']??'')==='Accounts Approved / Posted';if(!$active&&$asOf!==null&&($r['status']??'')==='Reversed for Amendment'){$rev=$r['reversalPostIds'][$r['journalId']??'']??null;$active=$rev&&($s['journals'][$rev]['date']??'')>$asOf;}$amount=round((float)($r['forwardUsdUsed']??0),2);if($active)$used=round($used+$amount,2);$history[]=['receiptId'=>$r['id'],'journalId'=>$r['journalId']??'','date'=>$r['date'],'advice'=>$r['bankAdviceRef']??'','remitter'=>$r['remitter']??'','receivingBank'=>$r['bankName']??'','usd'=>$amount,'rate'=>$r['realizationRate'],'active'=>$active,'status'=>$r['status'],'documents'=>array_values(array_filter(array_map(static fn($a)=>trim(implode(' · ',array_filter([$a['contractRef']??'',$a['invoiceRef']??'']))),(array)($r['allocations']??[]))))];}
 usort($history,static fn($a,$b)=>strcmp($a['date'],$b['date'])?:strcmp($a['receiptId'],$b['receiptId']));$balance=(float)$b['amountUsd'];foreach($history as &$item){if($item['active'])$balance=round($balance-$item['usd'],2);$item['balanceAfterUsd']=$balance;}unset($item);return ['usedUsd'=>$used,'remainingUsd'=>max(0,round($b['amountUsd']-$used,2)),'utilisations'=>$history];
}
function fwb_rows(array $s,string $e,string $asOf):array {
 fwb_entity($e);fwb_date($asOf,true);$out=[];
 foreach((array)($s['forwardBookings']??[]) as $b){if(($b['entity']??'')!==$e||$b['bookingDate']>$asOf)continue;$r=$b+fwb_usage($s,$b,$asOf);$closed=($b['status']??'')==='Settled'&&($b['settlement']['date']??'')<=$asOf;$cancelled=($b['status']??'')==='Cancelled'&&($b['cancelledAtDate']??'')<=$asOf;
 $r['state']=$cancelled?'Cancelled':($closed?'Settled':($r['remainingUsd']<=.005?'Fully utilised':($asOf<$b['startDate']?'Waiting':($asOf>$b['expiryDate']?'Expired — settlement pending':'Available'))));if(!$closed)unset($r['settlement']);$r['eligible']=$r['state']==='Available'&&($b['status']??'Open')==='Open';$r['unsettledUsd']=$closed||$cancelled?0:$r['remainingUsd'];$out[]=$r;
 }usort($out,static fn($a,$b)=>strcmp($a['bookingDate'],$b['bookingDate'])?:strcmp($a['id'],$b['id']));return $out;
}
function fwb_save(array &$s,string $e,array $in,array $u):array {
 fwb_entity($e);$id=trim((string)($in['id']??''));$old=$id!==''?($s['forwardBookings'][$id]??null):null;if($id!==''&&(!$old||$old['entity']!==$e))throw new DomainException('Forward booking not found in these company books.');if($old&&$old['status']!=='Open')throw new DomainException('This booking is closed; retain its history.');
 $bank=fwb_bank($e,(string)($in['bankAccountId']??''));$date=fwb_date($in['bookingDate']??'');$ab=fwb_days($in['waitingDays']??'',true);$cd=fwb_days($in['windowDays']??'',false);$start=(new DateTimeImmutable($date))->modify('+'.$ab.' days')->format('Y-m-d');$expiry=(new DateTimeImmutable($start))->modify('+'.$cd.' days')->format('Y-m-d');
 $row=['id'=>$id?:'fwd-'.bin2hex(random_bytes(12)),'entity'=>$e,'bankAccountId'=>$bank['id'],'bankName'=>$bank['name'],'bankLabel'=>$bank['label'],'bookingDate'=>$date,'amountUsd'=>fwb_number($in['amountUsd']??null,'USD amount'),'rate'=>fwb_number($in['rate']??null,'forward rate',6),'waitingDays'=>$ab,'windowDays'=>$cd,'startDate'=>$start,'expiryDate'=>$expiry,'contractNumber'=>fwb_text($in['contractNumber']??''),'note'=>fwb_text($in['note']??'',500),'status'=>'Open','createdAt'=>$old['createdAt']??gmdate('c'),'createdBy'=>$old['createdBy']??($u['username']??''),'updatedAt'=>gmdate('c'),'updatedBy'=>$u['username']??''];
 if($old&&fwb_usage($s,$old)['usedUsd']>.005)foreach(['bankAccountId','bookingDate','amountUsd','rate','waitingDays','windowDays'] as $field)if($row[$field]!=$old[$field])throw new DomainException('This booking has posted utilisations. Only its optional contract number and note can change until linked advices are reversed.');
 $s['forwardBookings'][$row['id']]=$row;$s['forwardBookingAudit'][]=['action'=>$old?'edit':'create','before'=>$old,'after'=>$row,'actor'=>$u['username']??'','at'=>gmdate('c')];return ['bookingId'=>$row['id']];
}
function fwb_prepare_receipt(array $s,string $e,string $date,string $currency,string $bankCurrency,float $foreign,float $retention,float $rate,string $id):array {
 $b=$s['forwardBookings'][$id]??null;if(!$b||$b['entity']!==$e||($b['status']??'')!=='Open')throw new DomainException('The selected forward booking is no longer available in these company books.');fwb_entity($e);fwb_date($date);
 if($currency!=='USD'||$bankCurrency!=='PKR')throw new DomainException('Forward bookings apply only to USD converted into a Pakistan company PKR bank.');if($date<$b['startDate']||$date>$b['expiryDate'])throw new DomainException('This advice date is outside the forward booking utilisation window.');
 if(abs($rate-(float)$b['rate'])>.0000005)throw new DomainException('The rate must equal the selected forward booking rate.');$usd=round($foreign-$retention,2);if($usd<=.005)throw new DomainException('Retained USD does not utilise a forward booking; select a manual rate.');$available=fwb_usage($s,$b)['remainingUsd'];if($usd>$available+.005)throw new DomainException('Only USD '.number_format($available,2).' remains in this booking. Post separate credit advices for the forward and manual-rate amounts.');
 return ['forwardBookingId'=>$id,'forwardUsdUsed'=>$usd,'forwardContractNumber'=>$b['contractNumber'],'forwardRate'=>$b['rate'],'forwardBookingBankId'=>$b['bankAccountId']];
}
function fwb_assert_receipt_reversible(array $s,array $r):void {$id=$r['forwardBookingId']??'';if($id!==''&&($s['forwardBookings'][$id]['status']??'')==='Settled')throw new DomainException('Reverse this forward booking expiry settlement before reversing or amending its utilised credit advice.');}
function fwb_journal(array &$s,array $u,string $e,string $date,string $type,array $lines,array $meta,?string $reversal=null):array {
 $names=['1110'=>'Bank Accounts','7100'=>'Exchange Gain / Loss','6800'=>'Bank & Finance Charges'];foreach($lines as &$l)$l['accountName']=$names[$l['account']];unset($l);$dr=round(array_sum(array_column($lines,'debit')),2);$cr=round(array_sum(array_column($lines,'credit')),2);if($dr<=0||abs($dr-$cr)>.005)throw new DomainException('Forward settlement must balance.');$id=tt_next_post_id((array)($s['journals']??[]),'Accounts','Journal',$date);
 $j=['id'=>$id,'entity'=>$e,'date'=>$date,'sourceType'=>$type,'reference'=>$meta['contractNumber']??'','narration'=>strtoupper('Forward booking '.($reversal?'settlement reversal':'expiry settlement').' · '.($meta['bankName']??'').' · '.($meta['contractNumber']??'')),'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>$meta,'createdAt'=>gmdate('c'),'createdBy'=>$u['full_name']??$u['username']??'','userId'=>$u['id']??0,'reversalOf'=>$reversal];return $s['journals'][$id]=$j;
}
function fwb_settle(array &$s,string $e,array $in,array $u):array {
 fwb_entity($e);$id=(string)($in['id']??'');$b=$s['forwardBookings'][$id]??null;if(!$b||$b['entity']!==$e||$b['status']!=='Open')throw new DomainException('Choose an open forward booking.');$date=fwb_date($in['date']??'');if($date<$b['expiryDate'])throw new DomainException('Expiry settlement cannot be posted before the contract expiry date.');$bank=fwb_bank($e,$b['bankAccountId']);$usage=fwb_usage($s,$b);$usd=$usage['remainingUsd'];if(isset($in['expectedRemainingUsd'])&&abs($usd-(float)$in['expectedRemainingUsd'])>.005)throw new DomainException('The unused USD balance changed. Review this settlement again.');if($usd<=.005)throw new DomainException('This booking is fully utilised and has no unused USD to settle.');$closing=fwb_number($in['closingRate']??null,'bank-confirmed closing rate',6);$fees=fwb_number($in['fees']??0,'bank charges',2,true);$reason=fwb_text($in['note']??'',500);$fx=round($usd*($b['rate']-$closing),2);$net=round($fx-$fees,2);
 $lines=[];if($net!=0)$lines[]=['account'=>'1110','debit'=>max(0,$net),'credit'=>max(0,-$net),'bankAccountId'=>$bank['id'],'bankName'=>$bank['name'],'currency'=>'PKR','bankDebit'=>max(0,$net),'bankCredit'=>max(0,-$net)];if($fx!=0)$lines[]=['account'=>'7100','debit'=>max(0,-$fx),'credit'=>max(0,$fx),'subledger'=>'Forward Exchange Profit / Loss','fxDirection'=>$fx>0?'Gain':'Loss'];if($fees>0)$lines[]=['account'=>'6800','debit'=>$fees,'credit'=>0,'subledger'=>'Forward Booking Settlement Charges'];
 $meta=['forwardBookingId'=>$id,'contractNumber'=>$b['contractNumber'],'bankName'=>$bank['name'],'bankAccountId'=>$bank['id'],'unusedUsd'=>$usd,'forwardRate'=>$b['rate'],'closingRate'=>$closing,'fees'=>$fees,'profitLoss'=>$fx,'netBankAmount'=>$net,'note'=>$reason];$j=$lines?fwb_journal($s,$u,$e,$date,'FORWARD_BOOKING_SETTLEMENT',$lines,$meta):null;$record=$meta+['date'=>$date,'journalId'=>$j['id']??null,'at'=>gmdate('c'),'actor'=>$u['username']??''];$s['forwardBookings'][$id]['status']='Settled';$s['forwardBookings'][$id]['settlement']=$record;$s['forwardBookingAudit'][]=['action'=>'settle','bookingId'=>$id,'record'=>$record];return ['bookingId'=>$id,'journalId'=>$j['id']??null,'settlement'=>$record];
}
function fwb_reverse_settlement(array &$s,string $e,string $id,string $reason,array $u):array {
 fwb_entity($e);$b=$s['forwardBookings'][$id]??null;if(!$b||$b['entity']!==$e||$b['status']!=='Settled')throw new DomainException('Choose a settled booking.');$reason=fwb_text($reason,300);if(strlen($reason)<5)throw new DomainException('Enter a reversal reason of at least five characters.');$original=$b['settlement'];$j=null;
 if($original['journalId']){$old=$s['journals'][$original['journalId']]??null;if(!$old||!empty($old['reversedByPostId']))throw new DomainException('The settlement posting is already reversed or unavailable.');$lines=$old['lines'];foreach($lines as &$l){[$l['debit'],$l['credit']]=[$l['credit'],$l['debit']];if(isset($l['bankDebit']))[$l['bankDebit'],$l['bankCredit']]=[$l['bankCredit'],$l['bankDebit']];}unset($l);$j=fwb_journal($s,$u,$e,$original['date'],'FORWARD_BOOKING_SETTLEMENT_REVERSAL',$lines,$old['meta']+['reason'=>$reason],$old['id']);$s['journals'][$old['id']]['reversedByPostId']=$j['id'];}
 $s['forwardBookings'][$id]['settlementHistory'][]=$original+['reversalJournalId'=>$j['id']??null,'reversalReason'=>$reason];unset($s['forwardBookings'][$id]['settlement']);$s['forwardBookings'][$id]['status']='Open';$s['forwardBookingAudit'][]=['action'=>'reverse_settlement','bookingId'=>$id,'before'=>$original,'reason'=>$reason,'actor'=>$u['username']??'','at'=>gmdate('c')];return ['bookingId'=>$id,'journalId'=>$j['id']??null];
}
function fwb_cancel(array &$s,string $e,string $id,string $reason,array $u):array {$b=$s['forwardBookings'][$id]??null;if(!$b||$b['entity']!==fwb_entity($e)||$b['status']!=='Open')throw new DomainException('Choose an open booking.');if(fwb_usage($s,$b)['usedUsd']>.005)throw new DomainException('Reverse utilised credit advices before cancelling the booking.');$reason=fwb_text($reason,300);if(strlen($reason)<5)throw new DomainException('Enter a cancellation reason of at least five characters.');$s['forwardBookings'][$id]['status']='Cancelled';$s['forwardBookings'][$id]['cancelledAtDate']=fwb_today();$s['forwardBookingAudit'][]=['action'=>'cancel','bookingId'=>$id,'reason'=>$reason,'actor'=>$u['username']??'','at'=>gmdate('c')];return ['bookingId'=>$id];}
